window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c6c32809ac3e466"]={"versions": [{"id": "FIG-5c6c32809ac3e466", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Paketformat-Diagramm eines Service Entry im SOME/IP Service Discovery (SOME/IP-SD) Protokoll. Das Diagramm spezifiziert die 16 Byte (128 Bit) umfassende binäre Struktur eines Service Entry innerhalb des Entry-Arrays von SOME/IP-SD-Nachrichten. Es ist horizontal in 32-Bit-Worte (Bit 0 bis 31) unterteilt und gliedert die Protokollfelder zur Adressierung, Versionierung und Verwaltung von Service-Instanzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format besteht aus vier 32-Bit-Zeilen mit folgenden Feldern und Bitbreiten:</p>\n<ul class=\"fig-list\"><li><strong>Type</strong> (Bit 0–7, 8 Bit / uint8): Gibt den Eintragstyp an (z. B. FindService 0x00, OfferService 0x01).\n</li><li><strong>Index 1st options</strong> (Bit 8–15, 8 Bit / uint8): Index des ersten zugehörigen Options-Laufs im Options-Array.\n</li><li><strong>Index 2nd options</strong> (Bit 16–23, 8 Bit / uint8): Index des zweiten zugehörigen Options-Laufs im Options-Array.\n</li><li><strong># of opt 1</strong> (Bit 24–27, 4 Bit / uint4): Anzahl der vom ersten Options-Lauf referenzierten Optionen.\n</li><li><strong># of opt 2</strong> (Bit 28–31, 4 Bit / uint4): Anzahl der vom zweiten Options-Lauf referenzierten Optionen.\n</li><li><strong>Service ID</strong> (Bit 0–15, 16 Bit / uint16): Eindeutige Kennung des SOME/IP-Dienstes.\n</li><li><strong>Instance ID</strong> (Bit 16–31, 16 Bit / uint16): Instanzkennung des Dienstes (oder 0xFFFF für alle Instanzen).\n</li><li><strong>Major Version</strong> (Bit 0–7, 8 Bit / uint8): Hauptversionsnummer des Service-Interfaces.\n</li><li><strong>TTL</strong> (Time to Live, Bit 8–31, 24 Bit / uint24): Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><strong>Minor Version</strong> (Bit 0–31, 32 Bit / uint32): Nebenversionsnummer des Service-Interfaces.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Feldspezifikation für Serialisierung und Deserialisierung. Bei der Service Discovery steuert der Service Entry den Discovery-Ablauf:</p>\n<ul class=\"fig-list\"><li>Ein Client sendet einen Service Entry vom Typ FindService, um Instanzen eines Dienstes im Netzwerk zu suchen.\n</li><li>Ein Server antwortet mit einem Service Entry vom Typ OfferService (oder sendet diesen zyklisch/ereignisgesteuert), um die Verfügbarkeit und Adressierungsinformationen (über referenzierte Optionen) bekanntzugeben.\n</li><li>Die Lebensdauer der Service-Bekanntmachung wird über das TTL-Feld gesteuert (TTL = 0 signalisiert StopOfferService). Option-Indizes und -Zähler binden Endpoint- und Konfigurations-Optionen aus dem gemeinsamen Options-Array an den Eintrag.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Wire-Format für Service Entries im SOME/IP-SD-Protokoll:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge beträgt exakt 16 Byte (128 Bit); Alignment und Byte-Reihenfolge (Big-Endian / Network Byte Order) sind strikt einzuhalten.\n</li><li>Bit 24 bis 31 des ersten 32-Bit-Worts teilen sich in zwei 4-Bit-Nibbles (# of opt 1 und # of opt 2).\n</li><li>Das TTL-Feld ist 24 Bit breit und belegt zusammen mit der 8 Bit breiten Major Version genau das dritte 32-Bit-Wort.\n</li><li>Implementierer müssen sicherstellen, dass die Options-Referenzen (Index 1st/2nd options sowie # of opt 1/2) konsistent auf gültige Einträge im nachgelagerten Options-Array des SOME/IP-SD-Headers verweisen.\n</li></ul>"}, {"id": "FIG-c73df11f81ac51b0", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Paketformat-Diagramm eines Service Entry im SOME/IP Service Discovery (SOME/IP-SD) Protokoll. Das Diagramm spezifiziert die 16 Byte (128 Bit) umfassende binäre Struktur eines Service Entry innerhalb des Entry-Arrays von SOME/IP-SD-Nachrichten. Es ist horizontal in 32-Bit-Worte (Bit 0 bis 31) unterteilt und gliedert die Protokollfelder zur Adressierung, Versionierung und Verwaltung von Service-Instanzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format besteht aus vier 32-Bit-Zeilen mit folgenden Feldern und Bitbreiten:</p>\n<ul class=\"fig-list\"><li><strong>Type</strong> (Bit 0–7, 8 Bit / uint8): Gibt den Eintragstyp an (z. B. FindService 0x00, OfferService 0x01).\n</li><li><strong>Index 1st options</strong> (Bit 8–15, 8 Bit / uint8): Index des ersten zugehörigen Options-Laufs im Options-Array.\n</li><li><strong>Index 2nd options</strong> (Bit 16–23, 8 Bit / uint8): Index des zweiten zugehörigen Options-Laufs im Options-Array.\n</li><li><strong># of opt 1</strong> (Bit 24–27, 4 Bit / uint4): Anzahl der vom ersten Options-Lauf referenzierten Optionen.\n</li><li><strong># of opt 2</strong> (Bit 28–31, 4 Bit / uint4): Anzahl der vom zweiten Options-Lauf referenzierten Optionen.\n</li><li><strong>Service ID</strong> (Bit 0–15, 16 Bit / uint16): Eindeutige Kennung des SOME/IP-Dienstes.\n</li><li><strong>Instance ID</strong> (Bit 16–31, 16 Bit / uint16): Instanzkennung des Dienstes (oder 0xFFFF für alle Instanzen).\n</li><li><strong>Major Version</strong> (Bit 0–7, 8 Bit / uint8): Hauptversionsnummer des Service-Interfaces.\n</li><li><strong>TTL</strong> (Time to Live, Bit 8–31, 24 Bit / uint24): Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><strong>Minor Version</strong> (Bit 0–31, 32 Bit / uint32): Nebenversionsnummer des Service-Interfaces.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Feldspezifikation für Serialisierung und Deserialisierung. Bei der Service Discovery steuert der Service Entry den Discovery-Ablauf:</p>\n<ul class=\"fig-list\"><li>Ein Client sendet einen Service Entry vom Typ FindService, um Instanzen eines Dienstes im Netzwerk zu suchen.\n</li><li>Ein Server antwortet mit einem Service Entry vom Typ OfferService (oder sendet diesen zyklisch/ereignisgesteuert), um die Verfügbarkeit und Adressierungsinformationen (über referenzierte Optionen) bekanntzugeben.\n</li><li>Die Lebensdauer der Service-Bekanntmachung wird über das TTL-Feld gesteuert (TTL = 0 signalisiert StopOfferService). Option-Indizes und -Zähler binden Endpoint- und Konfigurations-Optionen aus dem gemeinsamen Options-Array an den Eintrag.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Wire-Format für Service Entries im SOME/IP-SD-Protokoll:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge beträgt exakt 16 Byte (128 Bit); Alignment und Byte-Reihenfolge (Big-Endian / Network Byte Order) sind strikt einzuhalten.\n</li><li>Bit 24 bis 31 des ersten 32-Bit-Worts teilen sich in zwei 4-Bit-Nibbles (# of opt 1 und # of opt 2).\n</li><li>Das TTL-Feld ist 24 Bit breit und belegt zusammen mit der 8 Bit breiten Major Version genau das dritte 32-Bit-Wort.\n</li><li>Implementierer müssen sicherstellen, dass die Options-Referenzen (Index 1st/2nd options sowie # of opt 1/2) konsistent auf gültige Einträge im nachgelagerten Options-Array des SOME/IP-SD-Headers verweisen.\n</li></ul>"}], "trans": [{"from": "FIG-5c6c32809ac3e466", "to": "FIG-c73df11f81ac51b0", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c73df11f81ac51b0", "to": "FIG-5c6c32809ac3e466", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
